"use client";

import * as React from "react";
import Link from "next/link";
import { LogOut, Settings } from "lucide-react";
import { Avatar } from "./avatar";

export type AccountMenuProps = {
  userName?: string | null;
  userEmail?: string | null;
  userImage?: string | null;
  onSignOut?: (formData: FormData) => void | Promise<void>;
};

export function AccountMenu({ userName, userEmail, userImage, onSignOut }: AccountMenuProps) {
  const [open, setOpen] = React.useState(false);
  const buttonRef = React.useRef<HTMLButtonElement | null>(null);
  const menuRef = React.useRef<HTMLDivElement | null>(null);

  React.useEffect(() => {
    function onDocClick(e: MouseEvent) {
      if (!open) return;
      const t = e.target as Node;
      if (buttonRef.current?.contains(t)) return;
      if (menuRef.current?.contains(t)) return;
      setOpen(false);
    }
    function onEsc(e: KeyboardEvent) {
      if (e.key === "Escape") setOpen(false);
    }
    document.addEventListener("mousedown", onDocClick);
    document.addEventListener("keydown", onEsc);
    return () => {
      document.removeEventListener("mousedown", onDocClick);
      document.removeEventListener("keydown", onEsc);
    };
  }, [open]);

  const initials = (userName ?? userEmail ?? "User");

  return (
    <div className="relative">
      <button
        ref={buttonRef}
        aria-haspopup="menu"
        aria-expanded={open}
        onClick={() => setOpen((v) => !v)}
        className="group relative inline-flex items-center gap-2 rounded-full border border-border bg-card p-0.5 pr-2 hover:bg-card2"
        title="Account"
      >
        <Avatar src={userImage ?? undefined} name={userName ?? userEmail ?? undefined} size={32} />
        <span className="hidden sm:block text-sm text-text max-w-[12rem] truncate">
          {userName || userEmail || "Account"}
        </span>
      </button>

      {open && (
        <div
          ref={menuRef}
          role="menu"
          className="absolute right-0 z-20 mt-2 w-64 overflow-hidden rounded-lg border border-border bg-card shadow-lg"
        >
          <div className="flex items-center gap-3 p-3 border-b border-border bg-card2">
            <Avatar src={userImage ?? undefined} name={userName ?? userEmail ?? undefined} size={40} />
            <div className="min-w-0">
              <div className="truncate text-sm font-medium text-text">{userName || initials}</div>
              {userEmail && <div className="truncate text-xs text-muted">{userEmail}</div>}
            </div>
          </div>

          <div className="p-1">
            <Link
              href="/settings"
              role="menuitem"
              className="flex items-center gap-2 rounded-md px-2 py-2 text-sm text-text hover:bg-card2"
              onClick={() => setOpen(false)}
            >
              <Settings className="h-4 w-4 text-accent" />
              Settings
            </Link>
          </div>

          <form action={onSignOut} className="p-1 border-t border-border">
            <button
              role="menuitem"
              type="submit"
              className="flex w-full items-center gap-2 rounded-md px-2 py-2 text-left text-sm text-text hover:bg-card2"
              onClick={() => setOpen(false)}
            >
              <LogOut className="h-4 w-4 text-accent" />
              Sign out
            </button>
          </form>
        </div>
      )}
    </div>
  );
}

export default AccountMenu;
